pub fn detect_gpu_info_sync() -> String { if let Some(gpu) = GpuContext::get() { let mut s = String::new(); s.push_str(&format!("GPU: {}
", gpu.adapter_info)); s.push_str(&format!( "Backend: wgpu 30.0.0 - Device limits: {:?}
", gpu.device.limits() )); s.push_str("Backends: Vulkan/Metal/DX12/WGL (auto)
"); s.push_str("Traitement nodal: GPU compute (branché) + fallback CPU rayon
"); s.push_str("Rendu canvas: WGPU via iced_wgpu (textures + shaders)
"); let cores = std::thread::available_parallelism() .map(|n| n.get()) .unwrap_or(4); s.push_str(&format!("CPU cores: {} (rayon global pool)
", cores)); // Force rayon pool à utiliser tous les cœurs s.push_str(&format!( "Rayon threads: {} (actifs)
", rayon::current_num_threads() )); s } else { let mut s = String::new(); s.push_str("GPU: non disponible - CPU seul
"); let cores = std::thread::available_parallelism() .map(|n| n.get()) .unwrap_or(4); s.push_str(&format!("CPU cores: {} (rayon)
", cores)); s.push_str(&format!( "Rayon threads: {}
", rayon::current_num_threads() )); s } }
